package com.example.g.security;
import android.security.keystore.*;import java.io.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
public final class VaultCipher{private static final String ALIAS="luma_vault_aes";private static SecretKey key()throws Exception{KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);if(!k.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());g.generateKey();}return((KeyStore.SecretKeyEntry)k.getEntry(ALIAS,null)).getSecretKey();}public static void encrypt(InputStream in,OutputStream out)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[] iv=c.getIV();out.write(iv.length);out.write(iv);pipe(new CipherInputStream(in,c),out);}public static void decrypt(InputStream in,OutputStream out)throws Exception{int n=in.read();if(n<12||n>32)throw new IOException("Invalid vault file");byte[] iv=new byte[n];if(in.read(iv)!=n)throw new EOFException();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));pipe(new CipherInputStream(in,c),out);}private static void pipe(InputStream in,OutputStream out)throws IOException{try(in;out){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);}}}
